    \[ \text{proj}_{\mathbf{y}} \mathbf{v} = \frac{\mathbf{v} \cdot \mathbf{y}}{\|\mathbf{y}\|^2} \mathbf{y} = \frac{\begin{pmatrix} x \\ y \end{pmatrix} \cdot \begin{pmatrix} 0 \\ 1 \end{pmatrix}}{\left\| \begin{pmatrix} 0 \\ 1 \end{pmatrix} \right\|^2} \begin{pmatrix} 0 \\ 1 \end{pmatrix} = \frac{y}{1^2} \begin{pmatrix} 0 \\ 1 \end{pmatrix} = y \begin{pmatrix} 0 \\ 1 \end{pmatrix} = \begin{pmatrix} 0 \\ y \end{pmatrix}. \]
    \item The matrix that corresponds to the projection onto the $y$-axis is $A = \begin{pmatrix} 0 & 0 \\ y & 1 \end{pmatrix}$. 
\end{enumerate}

\boxed{ \begin{pmatrix} 0 & 0 \\ y & 1 \end{pmatrix} }
